css:
.noc-doc { font-size: 9.5pt; }
.noc-doc table { width: 100%; border-collapse: collapse; }
.noc-doc th { background: #F1EFE8; text-align: left; padding: 5px 6px; font-weight: 500;
  border-bottom: 1px solid #B4B2A9; }
.noc-doc td { padding: 5px 6px; vertical-align: top; border-bottom: 0.5px solid #D3D1C7; }
.noc-part { font-family: monospace; font-size: 9pt; color: #185FA5; }
.noc-spec-wrap { padding: 4px 6px 8px 18px; }
.noc-spec-block td { border: none; padding: 1px 4px; font-size: 8.5pt; }
.noc-muted { color: #5F5E5A; font-size: 8.5pt; }
.noc-ar { direction: rtl; }
.noc-head { border-bottom: 1.5px solid #444441; padding-bottom: 6px; margin-bottom: 10px; }
.noc-annex { page-break-before: always; }
.noc-badge { background:#E6F1FB; color:#0C447C; padding:1px 5px; border-radius:3px; font-size:8pt; }
.noc-mod { background:#EAF3DE; color:#27500A; padding:1px 5px; border-radius:3px; font-size:8pt; }
